// Only creates metadata-only staged links. No process is launched by this tool.
using System;using System.Collections.Generic;using System.IO;using System.Reflection;using System.Runtime.InteropServices;using System.Web.Script.Serialization;
[StructLayout(LayoutKind.Sequential,Pack=4)]internal struct NativePropertyKey {internal Guid format;internal uint id;}
[StructLayout(LayoutKind.Explicit,Size=24)]internal struct NativePropVariant {[FieldOffset(0)]internal ushort type;[FieldOffset(8)]internal IntPtr pointer;[FieldOffset(16)]internal IntPtr padding;}
[ComImport,Guid("886d8eeb-8cf2-4446-8d02-cdba1dbdcf99"),InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]internal interface NativePropertyStore {
 [PreserveSig]int GetCount(out uint count);[PreserveSig]int GetAt(uint index,out NativePropertyKey key);[PreserveSig]int GetValue(ref NativePropertyKey key,out NativePropVariant value);[PreserveSig]int SetValue(ref NativePropertyKey key,ref NativePropVariant value);[PreserveSig]int Commit();}
internal static class ControlledShortcuts {
 const string Stage=__STAGE_ROOT__,TargetHash=__LAUNCHER_HASH__,FixtureDeploymentRoot=__SHORTCUT_TEST_ROOT__;
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,ExactSpelling=true,SetLastError=true)] [return:MarshalAs(UnmanagedType.Bool)]static extern bool CopyFileW(string source,string destination,[MarshalAs(UnmanagedType.Bool)]bool failIfExists);
 static string Hash(FileStream file){file.Position=0;string value;using(var hash=System.Security.Cryptography.SHA256.Create())value=BitConverter.ToString(hash.ComputeHash(file)).Replace("-","").ToLowerInvariant();file.Position=0;return value;}
 static string[] DeploymentPaths(){string desktop,programs;if(FixtureDeploymentRoot!=""){NativeFiles.Plain(FixtureDeploymentRoot);if(!Directory.Exists(FixtureDeploymentRoot))throw new InvalidOperationException("fixture destination");desktop=Path.Combine(FixtureDeploymentRoot,"Desktop");programs=Path.Combine(FixtureDeploymentRoot,"StartMenu","Programs");}else{desktop=Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);programs=Environment.GetFolderPath(Environment.SpecialFolder.Programs);if(String.IsNullOrWhiteSpace(desktop)||String.IsNullOrWhiteSpace(programs))throw new InvalidOperationException("known folders unavailable");}return new[]{Path.Combine(desktop,"Codex-Controlled.lnk"),Path.Combine(programs,"Codex-Controlled.lnk")};}
 [DllImport("shell32.dll",CharSet=CharSet.Unicode,ExactSpelling=true)]static extern int SHGetPropertyStoreFromParsingName(string name,IntPtr bind,uint flags,ref Guid iid,[MarshalAs(UnmanagedType.Interface)]out NativePropertyStore store);
 [DllImport("ole32.dll",ExactSpelling=true)]static extern int PropVariantClear(ref NativePropVariant value);
 static NativePropertyKey Key(){return new NativePropertyKey{format=new Guid("9F4C2855-9F79-4B39-A8D0-E1D42DE1D5F3"),id=5};}
 static NativePropertyStore Open(string file,uint flags){NativePropertyStore store;Guid iid=typeof(NativePropertyStore).GUID;Marshal.ThrowExceptionForHR(SHGetPropertyStoreFromParsingName(file,IntPtr.Zero,flags,ref iid,out store));return store;}
 static void PutAppId(string file){var store=Open(file,2);var key=Key();var value=new NativePropVariant{type=31,pointer=Marshal.StringToCoTaskMemUni(NativePlan.AppId)};try{Marshal.ThrowExceptionForHR(store.SetValue(ref key,ref value));Marshal.ThrowExceptionForHR(store.Commit());}finally{try{Marshal.ThrowExceptionForHR(PropVariantClear(ref value));}finally{Marshal.FinalReleaseComObject(store);}}}
 static string GetAppId(string file){var store=Open(file,0);var key=Key();var value=new NativePropVariant();try{Marshal.ThrowExceptionForHR(store.GetValue(ref key,out value));if(value.type!=31)throw new InvalidOperationException("AppID type");return Marshal.PtrToStringUni(value.pointer);}finally{try{Marshal.ThrowExceptionForHR(PropVariantClear(ref value));}finally{Marshal.FinalReleaseComObject(store);}}}
 static object Get(object instance,string name){return instance.GetType().InvokeMember(name,BindingFlags.GetProperty,null,instance,null);}
 static void Set(object instance,string name,object value){instance.GetType().InvokeMember(name,BindingFlags.SetProperty,null,instance,new object[]{value});}
 static object Shell(){return Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell",true));}
 static object Link(object shell,string file){return shell.GetType().InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{file});}
 static Dictionary<string,object> Read(string file){NativeFiles.Plain(file);using(NativeFiles.Open(file,1024*1024)){}var shell=Shell();object link=null;try{link=Link(shell,file);string target=Convert.ToString(Get(link,"TargetPath")),arguments=Convert.ToString(Get(link,"Arguments")),working=Convert.ToString(Get(link,"WorkingDirectory")),icon=Convert.ToString(Get(link,"IconLocation"));int comma=icon.LastIndexOf(',');if(comma<0||icon.Substring(comma+1).Trim()!="0")throw new InvalidOperationException("icon index");string iconPath=icon.Substring(0,comma).Trim().Trim('"'),appId=GetAppId(file);if(!NativeFiles.Same(target,NativePlan.Executable)||arguments!=""||!NativeFiles.Same(working,NativePlan.OwnerRoot)||!NativeFiles.Same(iconPath,NativePlan.Icon)||appId!=NativePlan.AppId)throw new InvalidOperationException("shortcut binding");return new Dictionary<string,object>{{"path",file},{"target",target},{"arguments",arguments},{"workingDirectory",working},{"iconPath",iconPath},{"appUserModelId",appId}};}finally{if(link!=null)Marshal.FinalReleaseComObject(link);Marshal.FinalReleaseComObject(shell);}}
 static void Create(string file){var shell=Shell();object link=null;try{link=Link(shell,file);Set(link,"TargetPath",NativePlan.Executable);Set(link,"Arguments","");Set(link,"WorkingDirectory",NativePlan.OwnerRoot);Set(link,"IconLocation","\""+NativePlan.Icon+"\",0");Set(link,"WindowStyle",1);Set(link,"Description","Codex（受控流程）");link.GetType().InvokeMember("Save",BindingFlags.InvokeMethod,null,link,null);}finally{if(link!=null)Marshal.FinalReleaseComObject(link);Marshal.FinalReleaseComObject(shell);}PutAppId(file);}
 [STAThread]static int Main(string[] args){var held=new List<FileStream>();try{if(args.Length!=1||(args[0]!="stage"&&args[0]!="read"&&args[0]!="deploy")||IntPtr.Size!=8||Marshal.SizeOf(typeof(NativePropertyKey))!=20||Marshal.SizeOf(typeof(NativePropVariant))!=24)throw new InvalidOperationException("fixed action/layout");NativeFiles.Plain(Stage);
  foreach(var folder in new[]{Environment.SpecialFolder.DesktopDirectory,Environment.SpecialFolder.CommonDesktopDirectory,Environment.SpecialFolder.StartMenu,Environment.SpecialFolder.CommonStartMenu}){string real=Environment.GetFolderPath(folder);if(!String.IsNullOrEmpty(real)&&(NativeFiles.Inside(real,Stage)||NativeFiles.Inside(Stage,real)||FixtureDeploymentRoot!=""&&(NativeFiles.Inside(real,FixtureDeploymentRoot)||NativeFiles.Inside(FixtureDeploymentRoot,real))))throw new InvalidOperationException("real desktop/start menu is not a stage or fixture");}
  NativeFiles.Pin(NativePlan.Config,NativePlan.ConfigHash,2*1024*1024,held);NativeFiles.Pin(NativePlan.Manifest,NativePlan.ManifestHash,16*1024*1024,held);NativeFiles.Pin(NativePlan.Entry,NativePlan.EntryHash,32*1024*1024,held);NativeFiles.Pin(NativePlan.Executable,TargetHash,16*1024*1024,held);NativeFiles.Pin(NativePlan.Icon,NativePlan.IconHash,512L*1024*1024,held);
  var paths=new[]{Path.Combine(Stage,"Desktop","Codex-Controlled.lnk"),Path.Combine(Stage,"StartMenu","Codex-Controlled.lnk")};foreach(string file in paths){NativeFiles.Plain(file);if(args[0]=="stage"&&(File.Exists(file)||Directory.Exists(file)))throw new InvalidOperationException("existing stage target");}
  if(args[0]=="stage")foreach(string file in paths){NativeFiles.DirectoryPlain(Path.GetDirectoryName(file));Create(file);}var result=new List<Dictionary<string,object>>();foreach(string file in paths)result.Add(Read(file));
  if(args[0]=="deploy"){var targets=DeploymentPaths();var hashes=new List<string>();foreach(string source in paths){var stream=NativeFiles.Open(source,1024*1024);held.Add(stream);hashes.Add(Hash(stream));}foreach(string target in targets){NativeFiles.Plain(target);if(File.Exists(target)||Directory.Exists(target))throw new InvalidOperationException("existing deployment target");if(NativeFiles.Inside(Stage,target)||NativeFiles.Inside(NativePlan.Payload,target)||NativeFiles.Inside(NativePlan.OwnerRoot,target))throw new InvalidOperationException("deployment target boundary");}for(int i=0;i<targets.Length;i++){NativeFiles.DirectoryPlain(Path.GetDirectoryName(targets[i]));if(!CopyFileW(paths[i],targets[i],true))throw new InvalidOperationException("exclusive deployment copy refused");NativeFiles.Pin(targets[i],hashes[i],1024*1024,held);}result.Clear();foreach(string target in targets)result.Add(Read(target));}
  Console.OutputEncoding=new System.Text.UTF8Encoding(false);Console.WriteLine(new JavaScriptSerializer().Serialize(new Dictionary<string,object>{{"status",args[0]=="stage"?"staged":args[0]=="deploy"?"deployed":"read"},{"shortcuts",result},{"realDesktopChanged",args[0]=="deploy"&&FixtureDeploymentRoot==""},{"applicationStarted",false}}));return 0;
 }catch{Console.Error.WriteLine("Native shortcut staging/readback refused.");return 1;}finally{foreach(var file in held)file.Dispose();}}
}
